using System.Collections.Generic;
using UnityEngine;

namespace PixelPunch3D
{
    /// <summary>
    /// Sound effects and music from Resources/Audio (the same WAVs the Flutter
    /// app uses, generated by tools/generate_audio.py). Positional sounds play
    /// in 3D so you can hear where fights are happening.
    /// </summary>
    public class AudioBank : MonoBehaviour
    {
        static AudioBank _instance;
        readonly Dictionary<string, AudioClip> _clips = new();
        AudioSource _music;
        AudioSource _ui;

        public static float SfxVolume = 1f;
        public static float MusicVolume = 0.6f;

        public static void EnsureCreated()
        {
            if (_instance != null) return;
            var go = new GameObject("AudioBank");
            DontDestroyOnLoad(go);
            _instance = go.AddComponent<AudioBank>();
            _instance._music = go.AddComponent<AudioSource>();
            _instance._music.loop = true;
            _instance._music.spatialBlend = 0f;
            _instance._ui = go.AddComponent<AudioSource>();
            _instance._ui.spatialBlend = 0f;
        }

        static AudioClip Clip(string name)
        {
            EnsureCreated();
            if (_instance._clips.TryGetValue(name, out var clip)) return clip;
            clip = Resources.Load<AudioClip>($"Audio/{name}");
            if (clip == null) Debug.LogWarning($"[Audio] Missing clip Audio/{name}");
            _instance._clips[name] = clip;
            return clip;
        }

        public static void Play2D(string name, float volume = 1f)
        {
            var clip = Clip(name);
            if (clip != null) _instance._ui.PlayOneShot(clip, volume * SfxVolume);
        }

        public static void PlayAt(string name, Vector3 position, float volume = 1f)
        {
            var clip = Clip(name);
            if (clip == null) return;
            var go = new GameObject($"Sfx_{name}");
            go.transform.position = position;
            var src = go.AddComponent<AudioSource>();
            src.clip = clip;
            src.volume = volume * SfxVolume;
            src.spatialBlend = 1f;
            src.minDistance = 3f;
            src.maxDistance = 90f;
            src.rolloffMode = AudioRolloffMode.Linear;
            src.pitch = Random.Range(0.94f, 1.06f);
            src.Play();
            Destroy(go, clip.length + 0.1f);
        }

        public static void PlayMusic(string name, float volume = 0.6f)
        {
            var clip = Clip(name);
            if (clip == null) return;
            if (_instance._music.clip == clip && _instance._music.isPlaying) return;
            _instance._music.clip = clip;
            _instance._music.volume = volume * MusicVolume;
            _instance._music.Play();
        }

        public static void StopMusic()
        {
            if (_instance != null && _instance._music != null) _instance._music.Stop();
        }
    }
}
